 3	function getPreferredLanguage(acceptLanguage: string | null): string {
 4	  if (!acceptLanguage) {
 5	    return 'unknown';
 6	  }
 7	
 8	  const firstLanguage = acceptLanguage.split(',')[0]?.trim();
 9	  return firstLanguage || 'unknown';
10	}
